go:
package main
​
import (
    "bufio"
    "fmt"
    "os"
)
​
func main() {
    // 从标准输入读取一整行
    reader := bufio.NewReader(os.Stdin)
    s, _ := reader.ReadString('\n')
​
    letterCount := 0
    spaceCount := 0
    numberCount := 0
    otherCount := 0
​
    for _, c := range s {
        // 是否为英文
        if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') {
            letterCount++
        // 数字
        } else if c >= '0' && c <= '9' {
            numberCount++
        // 空格
        } else if c == ' ' {
            spaceCount++
        } else if c != '\n' && c != '\r' {
            otherCount++
        }
    }
​
    fmt.Println(letterCount)
    fmt.Println(spaceCount)
    fmt.Println(numberCount)
    fmt.Println(otherCount)
}
